    @push('scripts')<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script><script>let questionChart;function renderQuestionChart(values){const ctx=document.getElementById('questionChart');if(!ctx)return;if(questionChart)questionChart.destroy();questionChart=new Chart(ctx,{type:'bar',data:{labels:['Q1','Q2','Q3','Q4','Q5'],datasets:[{data:values,backgroundColor:['#173d78','#2563eb','#3d7be8','#6b9bea','#9db8e8'],borderRadius:9,barThickness:30}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{displayColors:false,callbacks:{label:(c)=>` ${c.raw}% de acerto`}}},scales:{x:{grid:{display:false},border:{display:false}},y:{beginAtZero:true,max:100,grid:{color:'#eef1f6'},border:{display:false},ticks:{callback:(v)=>v+'%'}}}}});}document.addEventListener('livewire:init',()=>{renderQuestionChart(@js($stats['questoes']??[0,0,0,0,0]));Livewire.hook('morph.updated',()=>setTimeout(()=>renderQuestionChart(@js($stats['questoes']??[0,0,0,0,0])),30));});</script>@endpush
